const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format((c||0)/100);
async function api(p,data){const r=await fetch('/api/admin/'+p,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'Operation failed');return v;}
const table=(columns,rows)=>rows.length?`<div class="scroll"><table><thead><tr>${columns.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p class="empty">No records yet.</p>';
const card=(name,value,note='')=>`<div class="card"><span class="muted">${name}</span><b>${value}</b><span class="muted">${note}</span></div>`;
export async function mount(root,message,page,state){const $=s=>root.querySelector(s);
 if(page==='Business settings'){
 const {business:b}=await api('business');root.innerHTML=`<form class="panel" data-business><h2>Business information</h2><p class="muted">These details are saved on new invoices and price quotes. Existing documents keep their business details.</p><div class="form-grid">${[['name','Business name'],['email','Business email'],['phone','Phone'],['address','Address'],['taxId','Tax registration number']].map(([k,l])=>`<label>${l}<input name="${k}" value="${esc(b[k])}" ${k==='name'?'required':''} ${k==='email'?'type="email"':''}></label>`).join('')}<label>Default tax (%)<input name="tax" type="number" min="0" max="30" step=".01" value="${b.tax}"></label><label class="wide">Default payment terms<textarea name="terms" rows="4">${esc(b.terms)}</textarea></label></div><div class="toolbar" style="margin-top:24px"><button class="primary">Save business information</button><span class="muted">Currency: CAD</span></div></form>`;
 $('[data-business]').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.tax=Number(data.tax);await api('business',data);message('Business information saved.');}catch(err){message(err.message,true);}finally{e.submitter.disabled=false;}};return;
 }
 if(page==='Payments'){
 const {payments}=await api('payments');root.innerHTML=`<div class="cards">${card('Recorded payments',money(payments.reduce((s,p)=>s+p.amount,0)),'Latest 1,000 ledger entries')}${card('Transactions',payments.length,'Money already received')}</div><div class="panel"><h2>All payments</h2><p class="muted">Manual payments recorded against invoices. Online checkout is not connected.</p><div class="toolbar"><input type="search" data-search placeholder="Search customer or reference"><button data-export>Export CSV</button></div><div data-ledger></div></div>`;
 const filtered=()=>payments.filter(p=>[p.customer,p.reference,p.title].join(' ').toLowerCase().includes($('[data-search]').value.toLowerCase()));const draw=()=>{$('[data-ledger]').innerHTML=table(['Date','Customer / invoice','Amount','Method','Reference'],filtered().map(p=>[esc(p.created_at.slice(0,10)),`${esc(p.customer)}<br><button data-invoice="${p.document_id}">${esc(p.title||'Invoice')}</button>`,money(p.amount),esc(p.method),esc(p.reference)]));};$('[data-search]').oninput=draw;$('[data-export]').onclick=()=>csv('payments.csv',['Date','Customer','Amount CAD','Method','Reference'],filtered().map(p=>[p.created_at,p.customer,p.amount/100,p.method,p.reference]));root.onclick=e=>{const b=e.target.closest('[data-invoice]');if(b){sessionStorage.setItem('satinOpenInvoice',b.dataset.invoice);location.hash='Invoices';location.reload();}};draw();return;
 }
 if(page==='Pay Links'){
 const {invoices}=await api('invoices');root.innerHTML=`<div class="panel"><h2>Invoice pay links</h2><p class="muted">One stable link for the deposit and remaining balance. Create an invoice and mark it sent to generate its link. Card and PayPal checkout remain unavailable until connected.</p>${table(['Invoice','Customer','Balance','Status','Actions'],invoices.filter(i=>!['draft','cancelled'].includes(i.status)).map(i=>[esc(i.title),esc(i.customer),money(i.balance),`<span class="pill ${i.status}">${i.status.replaceAll('_',' ')}</span>`,`<button data-link="${i.id}">Get pay link</button>`]))}<p data-url></p></div>`;
 root.onclick=async e=>{const b=e.target.closest('[data-link]');if(!b)return;b.disabled=true;try{const result=await api('invoices/link',{id:b.dataset.link});$('[data-url]').innerHTML=`<a target="_blank" rel="noopener" href="${esc(result.url)}">Open Pay Invoice ↗</a><label>Share this link<input readonly value="${esc(result.url)}"></label>`;}catch(err){message(err.message,true);}finally{b.disabled=false;}};return;
 }
 if(page==='Calendar'){
 root.innerHTML='<div class="panel"><div class="toolbar"><h2>Appointment requests</h2><label>Month<input type="month" data-month value="'+new Date().toISOString().slice(0,7)+'"></label></div><p class="muted">Requested appointments in America/Toronto. Confirm or reschedule with your customer before changing the booking status.</p><div data-calendar></div></div>';
 const draw=()=>{const rows=state.requests.filter(r=>r.type==='booking'&&r.preferred_date.startsWith($('[data-month]').value)).sort((a,b)=>(a.preferred_date+a.preferred_time).localeCompare(b.preferred_date+b.preferred_time));$('[data-calendar]').innerHTML=rows.length?[...new Set(rows.map(r=>r.preferred_date))].map(day=>`<div class="calendar-day"><h3>${esc(day)}</h3>${table(['Time','Customer','Service','Status'],rows.filter(r=>r.preferred_date===day).map(r=>[esc(r.preferred_time),`${esc(r.name)}<br>${esc(r.email)}`,esc(r.service),`<span class="pill">${esc(r.status.replaceAll('_',' '))}</span>`]))}</div>`).join(''):'<p class="empty">No appointments requested this month.</p>';};$('[data-month]').onchange=draw;draw();return;
 }
 if(page==='Real-time'){
 root.innerHTML=`<div class="cards">${card('Measured active visitors',state.visitors.length,'Last 90 seconds · consenting visitors')}</div><div class="panel"><h2>Visitor activity</h2><p class="muted">City is approximate. Records expire after 24 hours; this is not a count of all site traffic. Use Refresh for the latest activity.</p>${table(['Page','City','Country','Last seen'],state.visitors.map(v=>[esc(v.path),esc(v.city),esc(v.country),esc(new Date(v.last_seen).toLocaleTimeString())]))}</div>`;return;
 }
 root.innerHTML=`${page==='Overview'?'<div class="panel welcome-panel"><div class="welcome-mark">M</div><div><h2>Welcome back, Mehrad</h2><p class="muted">Your business workspace · Satin Graphic</p></div></div>':''}<div class="toolbar"><label>Reporting period<select data-period>${[7,30,90,365].map(n=>`<option value="${n}" ${n===30?'selected':''}>Last ${n} days</option>`).join('')}</select></label><button data-export>Export report</button><span class="muted">Payments and activity on this website · CAD</span></div><div data-report></div>`;
 let report;async function draw(){const days=$('[data-period]').value;report=await api('reports?days='+days);const max=Math.max(1,...report.daily.map(d=>d.total)),submissions=report.requests.reduce((s,r)=>s+r.count,0),bookings=report.requests.filter(r=>r.type==='booking').reduce((s,r)=>s+r.count,0);$('[data-report]').innerHTML=`<div class="cards">${card('Amount paid',money(report.payments.total),'Payments recorded in this period')}${card('Outstanding invoices',money(report.invoices.outstanding),'Current balance · all time')}${card('Overdue invoices',money(report.invoices.overdue),'Current overdue balance')}${card('Form submissions',submissions,'Submitted in this period')}</div><div class="report-grid"><div class="panel"><h2>Recorded payments over time</h2>${report.daily.length?report.daily.map(d=>`<div class="report-bar-row"><span>${esc(d.date)}</span><div class="report-bar"><span style="width:${d.total/max*100}%"></span></div><b>${money(d.total)}</b></div>`).join(''):'<p class="empty">No payments recorded in this period.</p>'}<p class="muted">Includes manually recorded cash, bank and e-transfer payments. Online checkout is not connected.</p></div><div class="panel"><h2>Your next tasks</h2><div class="task-row"><span>${state.requests.filter(r=>r.status==='pending_confirmation').length} requests awaiting confirmation</span><a class="button" href="#Requests%20%26%20bookings" data-route="Requests & bookings">Review</a></div><div class="task-row"><span>${report.invoices.count} saved invoices</span><a class="button" href="#Invoices" data-route="Invoices">View</a></div><div class="task-row"><span>${report.customers} customers</span><a class="button" href="#Customers" data-route="Customers">Contacts</a></div><div class="task-row"><span>${bookings} booking requests this period</span><a class="button" href="#Calendar" data-route="Calendar">Calendar</a></div></div></div><div class="panel" style="margin-top:24px"><h2>Form and booking activity</h2>${table(['Type','Status','Submissions'],report.requests.map(r=>[esc(r.type),esc(r.status.replaceAll('_',' ')),r.count]))}</div>`;}
 $('[data-period]').onchange=()=>draw().catch(e=>message(e.message,true));$('[data-export]').onclick=()=>csv('business-report.csv',['Metric','Value','Period'],[['Payments CAD',report.payments.total/100,'Last '+report.days+' days'],['Outstanding CAD',report.invoices.outstanding/100,'All time'],['Overdue CAD',report.invoices.overdue/100,'All time'],['Customers',report.customers,'All time'],...report.daily.map(d=>['Paid CAD '+d.date,d.total/100,'Daily'])]);root.onclick=e=>{const a=e.target.closest('[data-route]');if(a){e.preventDefault();location.hash=encodeURIComponent(a.dataset.route);location.reload();}};await draw();
}
function csv(name,columns,rows){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([[columns,...rows].map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
